// POST /iam/credentials/offers — the connector accepts a credential offered
// to it by the federation issuer, into its own W-Stack tenant (its wallet).
// Admin only: Authorization: Bearer <DSP_ADMIN_TOKEN>; no token configured
// refuses every call. Body: {"offer": "openid-credential-offer://..."} (the
// link the issuer gave), {"credential_offer_uri": "https://..."} or
// {"credential_offer": <offer JSON>}.
// Hands the offer to the tenant's retrieval service, which resolves it (issuer
// metadata) without accepting it yet.
// Outputs: 1 = retrieval request, 2 = answer to the caller.
const answer = (statusCode, body) => {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
    msg.payload = body;
    return [null, msg];
};
msg._recv = { correlationId: crypto.randomUUID() };

const admin = env.get('DSP_ADMIN_TOKEN') || '';
const auth = ((msg.req && msg.req.headers) || {}).authorization || '';
const m = /^Bearer\s+(\S+)$/i.exec(auth.trim());
const given = m ? Buffer.from(m[1]) : Buffer.alloc(0);
if (!admin || given.length !== Buffer.byteLength(admin) || !crypto.timingSafeEqual(given, Buffer.from(admin))) {
    msg._recv.result = 'unauthorized';
    return answer(401, { error: 'unauthorized' });
}

const base = (env.get('OCM_RETRIEVAL_URL') || '').replace(/\/+$/, '');
const tenant = env.get('OCM_TENANT') || '';
const group = env.get('OCM_ACCOUNT') || '';
if (!base || !tenant || !group) return answer(500, { error: 'config_missing', reason: 'OCM_RETRIEVAL_URL, OCM_TENANT and OCM_ACCOUNT are required' });

const b = msg.payload && typeof msg.payload === 'object' ? msg.payload : {};
// the retrieval service takes the offer as an offer link in either field
const LINK = 'openid-credential-offer://?';
let offer = null;
if (typeof b.offer === 'string') {
    try {
        const q = new url.URL(b.offer.replace(/^openid-credential-offer:\/\//, 'https://offer.invalid/')).searchParams;
        if (q.get('credential_offer_uri')) offer = { credential_offer_uri: b.offer };
        else if (q.get('credential_offer')) offer = { credential_offer: b.offer };
    } catch (e) {
        offer = null;
    }
} else if (typeof b.credential_offer_uri === 'string' && /^https:\/\//.test(b.credential_offer_uri)) {
    offer = { credential_offer_uri: LINK + 'credential_offer_uri=' + encodeURIComponent(b.credential_offer_uri) };
} else if (b.credential_offer && (typeof b.credential_offer === 'string' || typeof b.credential_offer === 'object')) {
    const json = typeof b.credential_offer === 'string' ? b.credential_offer : JSON.stringify(b.credential_offer);
    offer = { credential_offer: LINK + 'credential_offer=' + encodeURIComponent(json) };
}
if (!offer) return answer(400, { error: 'invalid_request', reason: 'credential_offer, credential_offer_uri or an openid-credential-offer:// link is required' });

msg._recv.base = base + '/v1/tenants/' + encodeURIComponent(tenant) + '/offering';
msg._recv.group = group;
msg.url = msg._recv.base + '/retrieve/' + encodeURIComponent(group);
msg.method = 'PUT';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = offer;
return [msg, null];

// The retrieval service answers the id of the offer it resolved, or refuses an
// offer it could not resolve or validate. Then read the resolved offer.
// Outputs: 1 = list request, 2 = answer to the caller.
const answer = (statusCode, body) => {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
    msg.payload = body;
    return [null, msg];
};
const code = msg.statusCode;
delete msg.statusCode;
if (code !== 200 || typeof msg.payload !== 'string' || !/^[0-9a-f-]{36}$/i.test(msg.payload)) {
    msg._recv.result = 'offer_refused_by_wallet';
    return answer(502, { error: 'offer_not_resolved', reason: 'the tenant retrieval service could not resolve or validate the offer' });
}
msg._recv.requestId = msg.payload;
msg.url = msg._recv.base + '/list/' + encodeURIComponent(msg._recv.group);
msg.method = 'GET';
msg.headers = { accept: 'application/json' };
msg.payload = '';
return [msg, null];

// Decide on the resolved offer before anything is issued:
//   - the issuer is a trusted one: its did:web (DSP_TRUSTED_ISSUERS) is the
//     offer's credential_issuer URL (did:web:host[:path] <-> https://host[/path]);
//   - every offered configuration is an SD-JWT VC (dc+sd-jwt) of the
//     participant credential type (vct = DSP_PARTICIPANT_VCT).
// Accept: the retrieval service runs OpenID4VCI with a proof signed by the
// tenant's key (OCM_KEY_NAMESPACE/OCM_KEY_GROUP/OCM_KEY), the key the
// credential then binds, and stores the credential. Refuse: the offer is
// deleted, nothing is issued.
// Outputs: 1 = clear request (accept or refuse), 2 = answer to the caller.
const answer = (statusCode, body) => {
    msg.statusCode = statusCode;
    msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
    msg.payload = body;
    return [null, msg];
};
const code = msg.statusCode;
delete msg.statusCode;
const rows = code === 200 && Array.isArray(msg.payload) ? msg.payload : null;
const row = rows && rows.find((r) => r && r.requestId === msg._recv.requestId);
if (!row) {
    msg._recv.result = 'offer_not_found';
    return answer(502, { error: 'offer_not_found', reason: 'the resolved offer is not in the tenant retrieval service' });
}

const didToUrl = (did) => {
    if (typeof did !== 'string' || !did.startsWith('did:web:')) return null;
    const segs = did.slice('did:web:'.length).split(':').map(decodeURIComponent);
    return 'https://' + segs.join('/');
};
const norm = (u) => String(u || '').replace(/\/+$/, '');
const offered = row.offering || {};
const meta = row.metadata || {};
const issuerUrl = norm(offered.credential_issuer);
const trusted = (env.get('DSP_TRUSTED_ISSUERS') || '').split(/[\s,]+/).filter(Boolean);
const issuerDid = trusted.find((d) => norm(didToUrl(d)) === issuerUrl);
const vct = env.get('DSP_PARTICIPANT_VCT') || '';
const ids = Array.isArray(offered.credential_configuration_ids) ? offered.credential_configuration_ids : [];
const confs = meta.credential_configurations_supported || {};
const bad = ids.length === 0 ? 'no configuration offered'
    : ids.find((id) => !confs[id] || confs[id].format !== 'dc+sd-jwt' || confs[id].vct !== vct);

msg._recv.issuer = issuerDid || issuerUrl || null;
msg._recv.configurations = ids;
let refusal = null;
if (!issuerDid) refusal = 'the offering issuer is not a trusted issuer: ' + (issuerUrl || 'none');
else if (!vct) refusal = 'DSP_PARTICIPANT_VCT not configured';
else if (bad) refusal = 'not a participant credential (dc+sd-jwt, vct ' + vct + '): ' + bad;

const ns = env.get('OCM_KEY_NAMESPACE') || '';
const key = env.get('OCM_KEY') || '';
if (!refusal && (!ns || !key)) refusal = 'OCM_KEY_NAMESPACE and OCM_KEY are required to accept';

msg._recv.accept = !refusal;
msg._recv.refusal = refusal;
msg.url = msg._recv.base + '/clear/' + encodeURIComponent(msg._recv.group) + '/' + encodeURIComponent(msg._recv.requestId);
msg.method = 'DELETE';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = refusal ? { accept: false } : { accept: true, holderKey: key, holderNamespace: ns, holderGroup: env.get('OCM_KEY_GROUP') || '' };
return [msg, null];

// The outcome. The credential itself is never returned or logged: the caller
// gets the request id, the issuer and the configuration; iam.issue reads the
// credential from the tenant storage when it presents it.
const code = msg.statusCode;
const r = msg._recv;
msg.headers = { 'Content-Type': 'application/json', 'Cache-Control': 'no-store' };
if (!r.accept) {
    r.result = 'refused';
    msg.statusCode = 403;
    msg.payload = { error: 'offer_refused', reason: r.refusal, requestId: r.requestId, deleted: code === 200 };
} else if (code === 200) {
    r.result = 'stored';
    msg.statusCode = 201;
    msg.payload = { status: 'stored', requestId: r.requestId, issuer: r.issuer, configurations: r.configurations };
} else {
    r.result = 'issuance_failed';
    msg.statusCode = 502;
    msg.payload = { error: 'issuance_failed', reason: 'the tenant retrieval service could not obtain or store the credential', requestId: r.requestId };
}
return msg;

// Every offer handled is logged as a structured event with its correlation id
// (no offer content, no credential).
const r = msg._recv || {};
const event = {
    event: 'iam.receive',
    correlationId: r.correlationId || null,
    at: new Date().toISOString(),
    result: r.result || null,
    requestId: r.requestId || null,
    issuer: r.issuer || null,
    configurations: r.configurations || null,
    reason: r.refusal || null
};
node.warn(JSON.stringify(event));
delete msg._recv;
return msg;
